/*
Day #15/24: Simply Connected
https://openprocessing.org/sketch/
https://mathober.com/2408633
https://openprocessing.org/curation/87980
*/

let S, pts;

function setup() {
  createCanvas(windowWidth, windowHeight);
	frameRate(60);
	background(0, 0, 8);
	describe("connection of moving points connecting lines from near-by points with slidely transparency giving blurry smeary background");

  noFill();
  strokeWeight(2);
	S = max(width, height) / 5;

	const num = sqrt(width+height);
	pts = [];
	for (let i = 0; i < num; i++) {
		// position
		const xp = constrain(randomGaussian(width/2, 100), width*0.1, width*0.9); // random(0.1, 0.9) * width;
		const yp = constrain(randomGaussian(height/2, 100), height*0.1, height*0.9); // random(0.1, 0.9) * height;
		// velocity
		const xv = random(0.25, 3) * (random() < 0.5 ? 1 : -1);
		const yv = random(0.25, 3) * (random() < 0.5 ? 1 : -1);
		// clr
		const clr = random() < 0.2 ? lerpColor(color("darkred"), color("purple"), random()) : lerpColor(color("cyan"), color("navy"), random());
		pts[i] = {xp, yp, xv, yv, clr};
	}

	loop();
}

function draw() {
	background(2, 2, 8, 32);

	for (let p of pts) {
		for (let o of pts) {
			if (p === o) continue;
			const dst = dist(p.xp, p.yp, o.xp, o.yp);
			if (dst < S) {
				stroke(lerpColor(p.clr, o.clr, 0.5));
				strokeWeight(map(dst, 0, S, 2, 0));
				line(p.xp, p.yp, o.xp, o.yp)
				// clrLine(p.xp, p.yp, o.xp, o.yp, p.clr, o.clr); // too slow
			}
		}
		stroke(p.clr)
		point(p.xp, p.yp);
		p.xp += p.xv;
		p.yp += p.yv;
		if (p.xp < 0 || p.xp > width-1) p.xv *= -1;
		if (p.yp < 0 || p.yp > width-1) p.yv *= -1;
	}

} // draw

function clrLine(x1, y1, x2, y2, c1, c2) {
	// const easings = [easeInOutElastic, easeInOutCubic, easeInCubic];
	// const easing = random(easings);
	var dst = dist(x1, y1, x2, y2);
	for (let i = 0; i <= dst; i++) {
		const f = i/dst;
		const x = lerp(x1, x2, f);
		const y = lerp(y1, y2, f);
		const c = lerpColor(c1, c2, f); // easing(f);
		stroke(c);
		point(x, y);
	}
}

function mouseClicked() {
  if (mouseButton === LEFT) setup();
}
